package com.lunaai.privatechat;

import android.app.Activity;
import android.os.Bundle;
import android.graphics.Color;
import android.content.SharedPreferences;
import android.content.Context;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.net.*;
import java.io.*;
import java.util.*;

public class MainActivity extends Activity {
  SharedPreferences prefs; LinearLayout root; EditText input; String selected="Luna";
  final int BG=Color.rgb(23,20,35); final int WHITE=Color.WHITE;
  void save(String k,String v){prefs.edit().putString(k,v).apply();}
  String get(String k,String fallback){return prefs.getString(k,fallback);}
  @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("luna",MODE_PRIVATE);selected=get("selected","Luna");chat();}
  TextView text(String t){TextView v=new TextView(this);v.setText(t);v.setTextSize(16);v.setTextColor(WHITE);v.setPadding(8,12,8,12);return v;}
  EditText field(String hint,String val){EditText e=new EditText(this);e.setTextColor(WHITE);e.setHintTextColor(Color.LTGRAY);e.setHint(hint);e.setText(val);root.addView(e);return e;}
  void btn(String title,Runnable action){Button b=new Button(this);b.setAllCaps(false);b.setText(title);root.addView(b);b.setOnClickListener(v->action.run());}
  void base(String title){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setBackgroundColor(BG);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,24,20,24);sc.addView(root);setContentView(sc);TextView h=text(title);h.setTextSize(24);root.addView(h);}
  String key(){return "history_"+selected;}
  JSONArray history(){try{return new JSONArray(get(key(),"[]"));}catch(Exception e){return new JSONArray();}}
  void add(String role,String content){try{JSONArray a=history();JSONObject o=new JSONObject();o.put("role",role);o.put("content",content);a.put(o);save(key(),a.toString());}catch(Exception ignored){}}
  void chat(){base("✦ LUNA AI · "+selected);btn("Karakterler",this::characters);btn("Görsel stüdyosu",this::images);btn("API ayarları",this::settings);JSONArray h=history();for(int i=0;i<h.length();i++){JSONObject m=h.optJSONObject(i);if(m!=null)root.addView(text(("user".equals(m.optString("role"))?"Sen: ":selected+": ")+m.optString("content")));}input=field("Mesaj yaz...","");btn("Gönder",()->{String msg=input.getText().toString().trim();if(msg.isEmpty())return;add("user",msg);chat();requestChat();});btn("Bu karakterin sohbetini sil",()->{save(key(),"[]");chat();});}
  void requestChat(){String endpoint=get("chat_endpoint","");String api=get("api_key","");String model=get("chat_model","");if(endpoint.isEmpty()||model.isEmpty()){toast("Önce API ayarlarında servis adresi ve model gir.");return;}root.addView(text("Yanıt bekleniyor..."));new Thread(()->{try{JSONObject body=new JSONObject();body.put("model",model);JSONArray messages=new JSONArray();messages.put(new JSONObject().put("role","system").put("content","Sen "+selected+" adında, yalnızca yetişkinlerle sohbet eden kurgusal bir karakterisin. Türkçe, doğal ve kullanıcıya saygılı konuş. Kişiliğin: "+get("persona_"+selected,"Samimi, flörtöz, neşeli")+". Gerçek insan olduğunu iddia etme."));JSONArray h=history();int start=Math.max(0,h.length()-20);for(int i=start;i<h.length();i++)messages.put(h.getJSONObject(i));body.put("messages",messages);JSONObject result=post(endpoint,api,body);String answer=result.getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content");add("assistant",answer);runOnUiThread(this::chat);}catch(Exception e){runOnUiThread(()->{toast("Bağlantı hatası: "+e.getMessage());chat();});}}).start();}
  JSONObject post(String endpoint,String api,JSONObject body)throws Exception{URL u=new URL(endpoint);if(!"https".equalsIgnoreCase(u.getProtocol()))throw new Exception("HTTPS gerekli");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setConnectTimeout(20000);c.setReadTimeout(90000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");if(!api.isEmpty())c.setRequestProperty("Authorization","Bearer "+api);try(OutputStream os=c.getOutputStream()){os.write(body.toString().getBytes("UTF-8"));}int status=c.getResponseCode();InputStream stream=status<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=stream.read(buffer))!=-1)bytes.write(buffer,0,n);String response=bytes.toString("UTF-8");if(status>=400)throw new Exception("HTTP "+status+": "+response.substring(0,Math.min(180,response.length())));return new JSONObject(response);}
  void characters(){base("Karakterler");String all=get("characters","Luna");for(String name:all.split("\\|")){if(name.trim().isEmpty())continue;btn("Sohbet: "+name,()->{selected=name;save("selected",name);chat();});}EditText name=field("Yeni karakter adı","");EditText persona=field("Karakterin kişiliği ve konuşma tarzı","");btn("Karakter oluştur",()->{String n=name.getText().toString().trim().replace("|","");if(n.isEmpty())return;if(!Arrays.asList(get("characters","Luna").split("\\|")).contains(n))save("characters",get("characters","Luna")+"|"+n);save("persona_"+n,persona.getText().toString());selected=n;save("selected",n);chat();});btn("Geri",this::chat);}
  void settings(){base("Servis Ayarları");root.addView(text("OpenAI uyumlu sohbet API'si kullan. Anahtar cihazda saklanır; şifreli kasa değildir. Güvenmediğin servise özel bilgilerini gönderme."));EditText endpoint=field("Sohbet endpoint HTTPS",get("chat_endpoint",""));EditText model=field("Model kimliği",get("chat_model",""));EditText api=field("API anahtarı",get("api_key",""));EditText image=field("Görsel endpoint HTTPS",get("image_endpoint",""));EditText imodel=field("Görsel model kimliği",get("image_model",""));btn("Ayarları kaydet",()->{save("chat_endpoint",endpoint.getText().toString().trim());save("chat_model",model.getText().toString().trim());save("api_key",api.getText().toString().trim());save("image_endpoint",image.getText().toString().trim());save("image_model",imodel.getText().toString().trim());chat();});btn("Geri",this::chat);}
  void images(){base("Görsel Stüdyosu · "+selected);root.addView(text("Bağlı servis images/generations biçimini desteklemelidir. Görsel yanıtı URL veya b64_json olarak dönebilir."));EditText prompt=field("Görsel tarifi",selected+", yetişkin kurgusal karakter, sinematik portre");btn("Görsel oluştur",()->{String endpoint=get("image_endpoint","");String model=get("image_model","");if(endpoint.isEmpty()||model.isEmpty()){toast("Görsel API ayarları eksik");return;}String description=prompt.getText().toString();root.addView(text("Görsel hazırlanıyor..."));new Thread(()->{try{JSONObject payload=new JSONObject().put("model",model).put("prompt",description).put("size","1024x1024");JSONObject result=post(endpoint,get("api_key",""),payload);JSONObject first=result.getJSONArray("data").getJSONObject(0);String b64=first.optString("b64_json","");String url=first.optString("url","");byte[] bytes;if(!b64.isEmpty()){bytes=android.util.Base64.decode(b64,android.util.Base64.DEFAULT);}else if(!url.isEmpty()&&url.startsWith("https://")){HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(20000);c.setReadTimeout(90000);try(InputStream is=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=is.read(buffer))!=-1)out.write(buffer,0,n);bytes=out.toByteArray();}}else throw new Exception("Görsel URL/b64 verisi bulunamadı");android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null)throw new Exception("Görsel okunamadı");runOnUiThread(()->{ImageView iv=new ImageView(this);iv.setImageBitmap(bitmap);iv.setAdjustViewBounds(true);root.addView(iv);toast("Görsel oluşturuldu");});}catch(Exception e){runOnUiThread(()->toast("Görsel hatası: "+e.getMessage()));}}).start();});btn("Geri",this::chat);}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
